// generated by audio/build_captions.py from voice/timemap.json: the picture was timed to the original read (old s);
// the voice was tightened (pauses cut to 0.20 s, tempo x1.12). Anchors (old s, new s), linear between.
export const ANCHORS: [number, number][] = [[0.0, 0.0], [3.15, 2.8125], [3.65, 2.9911], [5.69, 4.8125], [5.98, 4.9911], [9.36, 8.009], [9.83, 8.1875], [13.54, 11.5], [14.65, 11.6786], [16.89, 13.6786], [17.41, 13.8572], [18.26, 14.6161], [18.51, 14.7947], [19.96, 16.0893], [20.45, 16.2679], [23.11, 18.6429], [23.82, 18.8215], [25.25, 20.0983], [25.49, 20.2769], [27.04, 21.6608], [27.44, 21.8394], [32.65, 26.4912], [33.45, 26.6698], [34.36, 27.4823], [34.78, 27.6609], [35.75, 28.527], [36.26, 28.7055], [38.07, 30.3216], [38.54, 30.5001], [38.55, 30.509], [39.09, 30.6876], [40.89, 32.2947], [41.35, 32.4733], [43.61, 34.4912], [44.78, 34.6697], [47.87, 37.4286], [48.36, 37.6072], [51.33, 40.259], [51.8, 40.4376], [52.74, 41.2769], [53.08, 41.4555], [56.91, 44.8751], [57.4, 45.0537], [57.96, 45.5537], [58.49, 45.7323], [59.1, 46.2769], [59.79, 46.4555]];
const lerp = (pts: [number, number][], x: number, i: 0 | 1, j: 0 | 1) => {
  if (x <= pts[0][i]) return pts[0][j] + (x - pts[0][i]);
  for (let k = 1; k < pts.length; k++) if (x <= pts[k][i]) {
    const p = pts[k - 1], q = pts[k], d = q[i] - p[i];
    return d > 1e-9 ? p[j] + ((q[j] - p[j]) * (x - p[i])) / d : q[j];
  }
  const l = pts[pts.length - 1];
  return l[j] + (x - l[i]); // after the voice: real time (the tail)
};
/** original-read seconds -> final seconds */
export const toNew = (t: number) => lerp(ANCHORS, t, 0, 1);
/** final seconds -> original-read seconds (the picture runs on the original timeline) */
export const toOld = (t: number) => lerp(ANCHORS, t, 1, 0);
